/**
 * Billing period arithmetic: period boundaries, full-period charges and proration.
 */
import type { BillingInterval } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

export function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

function daysInMonthUtc(year: number, month: number): number {
  return new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
}

/** Same day `months` later at the same time, clamped to the month's last day. */
export function addMonthsClamped(start: Date, months: number): Date {
  const total = start.getUTCMonth() + months;
  const year = start.getUTCFullYear() + Math.floor(total / 12);
  const month = ((total % 12) + 12) % 12;
  const day = Math.min(start.getUTCDate(), daysInMonthUtc(year, month));
  return new Date(
    Date.UTC(
      year,
      month,
      day,
      start.getUTCHours(),
      start.getUTCMinutes(),
      start.getUTCSeconds(),
      start.getUTCMilliseconds(),
    ),
  );
}

/** The end of a period of `interval` starting at `start`. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  return addMonthsClamped(start, monthsInInterval(interval));
}

/** Full charge for one period, in cents. */
export function fullPeriodCharge(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}

/** Whole or started days from `at` to the period end; zero once it is reached. */
export function daysLeft(at: Date, periodEnd: Date): number {
  const ms = periodEnd.getTime() - at.getTime();
  return ms <= 0 ? 0 : Math.ceil(ms / MS_PER_DAY);
}

export function daysInPeriod(periodStart: Date, periodEnd: Date): number {
  return Math.max(
    1,
    Math.round((periodEnd.getTime() - periodStart.getTime()) / MS_PER_DAY),
  );
}

/** Scales a full-period amount by the days left over the days in the period. */
export function prorate(
  fullAmountCents: number,
  at: Date,
  periodStart: Date,
  periodEnd: Date,
): number {
  if (fullAmountCents <= 0) return 0;
  const total = daysInPeriod(periodStart, periodEnd);
  const left = Math.min(daysLeft(at, periodEnd), total);
  return Math.floor((fullAmountCents * left) / total);
}
EOF
