/**
 * Writes one invoice and announces it. The audit row and the owner's
 * notification are subscribers to `billing.invoice_issued`. A zero charge
 * issues nothing.
 */
export async function issueInvoice(
  orgId: OrgId,
  input: {
    amountCents: number;
    periodStart: IsoTimestamp;
    periodEnd: IsoTimestamp;
    now: Date;
  },
): Promise<Invoice | null> {
  if (input.amountCents <= 0) return null;

  const sequence = (await invoiceRepo.countInvoices(orgId)) + 1;
  const invoice = await invoiceRepo.insertInvoice(orgId, {
    orgId,
    number: `INV-${String(sequence).padStart(6, "0")}`,
    amountCents: input.amountCents,
    currency: "usd",
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    paidAt: null,
  });

  await emit("billing.invoice_issued", {
    orgId,
    actorId: null,
    occurredAt: toIsoTimestamp(input.now),
