/**
 * Renews subscriptions whose period has ended, invoicing every paid period,
 * and ends cancellations that have reached their date.
 *
 * Must call (do not reimplement): emit, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { fullPeriodCharge, periodEndFor } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Where an ended cancellation lands. */
const FALLBACK_PLAN = "free" as const;

const logger = createLogger("billing-renewal-job");

/**
 * Replay-safe: every step moves the stored period (or plan) forward before
 * anything is announced, so a second run at the same instant finds nothing due.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptionsOfLiveOrgs();

    for (const subscription of subscriptions) {
      try {
        const changed = await settle(subscription, now);
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function settle(subscription: Subscription, now: Date): Promise<boolean> {
  const orgId = subscription.orgId as OrgId;
  let current = subscription;
  let changed = false;

  if (current.status === "canceled") {
    if (current.cancelAt === null) return false;
    const cancelAt = new Date(current.cancelAt);
    if (cancelAt.getTime() > now.getTime()) return false;

    const from = current.plan;
    current = await subscriptionRepo.updateSubscriptionFields(orgId, {
      plan: FALLBACK_PLAN,
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: toIsoTimestamp(cancelAt),
      currentPeriodEnd: toIsoTimestamp(periodEndFor(cancelAt, "monthly")),
    });

    await emit("billing.plan_changed", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from,
      to: FALLBACK_PLAN,
    });
    changed = true;
  }

  if (current.status !== "active") return changed;

  while (new Date(current.currentPeriodEnd).getTime() <= now.getTime()) {
    const start = new Date(current.currentPeriodEnd);
    const periodStart = toIsoTimestamp(start);
    const periodEnd = toIsoTimestamp(periodEndFor(start, current.interval));

    current = await subscriptionRepo.updateSubscriptionFields(orgId, {
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
    });

    const price = getPlanLimits(current.plan).priceCentsPerSeatMonthly;
    await issueInvoice(orgId, {
      amountCents: fullPeriodCharge(price, current.seats, current.interval),
      periodStart,
      periodEnd,
      now,
    });
    changed = true;
  }

  return changed;
}
EOF
